components/ob-custom/global/ob-header:
{{inject 'theme_settings' theme_settings}}
{{inject 'main_settings' settings}}

<header class="header" role="banner">
    <div class="header--top">
        <div class="{{#if theme_settings.logo-position '==' 'left'}}logo-left {{else if theme_settings.logo-position '==' 'right'}}logo-right {{/if}}container">
            <a href="#" class="mobileMenu-toggle" data-mobile-menu-toggle="menu">
                <span class="mobileMenu-toggleIcon">Toggle menu</span>
            </a>

            <div class="navPages-quickSearch ob-desktop"></div>

            {{#if page_type '===' 'default'}}
                <h1 class="header-logo header-logo--{{theme_settings.logo-position}}">
                    {{> components/common/store-logo}}
                </h1>
            {{else}}
                <div class="header-logo header-logo--{{theme_settings.logo-position}}">
                    {{> components/common/store-logo}}
                </div>
            {{/if}}

            {{> components/ob-custom/global/ob-navigation}}
        </div>
    </div>
    <div class="header--bottom">
        <div class="container">
            <div class="header-promo ob-desktop ob-tablet-hidden">
                {{#if theme_settings.show_header_promo}}
                    {{> components/ob-custom/global/ob-header-promo}}
                {{/if}}
            </div>
            <div class="navPages-container" id="menu" data-menu>
                {{> components/ob-custom/global/ob-navigation-menu}}
            </div>
            <div class="header-beta-nav ob-desktop ob-tablet-hidden">
                {{#if theme_settings.show_gift_blog_links}}
                    {{#if settings.gift_certificates_enabled}}
                        <a class="beta-link gift-link"
                           href="{{urls.gift_certificate.purchase}}"
                           aria-label="{{lang 'common.gift_cert'}}"
                        >
                            {{#if theme_settings.theme_type '==' 'light'}}
                                <svg><use xlink:href="#icon-gift" /></svg>
                            {{/if}}
                            {{lang 'common.gift_cert'}}
                        </a>
                    {{/if}}
                    {{#if settings.blog_enabled}}
                        <a class="beta-link blog-link"
                           href="{{blog.url}}"
                           aria-label="{{blog.name}}"
                        >
                            {{blog.name}}
                        </a>
                    {{/if}}
                {{/if}}
            </div>
        </div>
    </div>
</header>

{{#if banners.top}}
<div class="banners" data-banner-location="top">
    {{#each (limit banners.top_metadata 1)}}
    <div class="banner" data-event-type="promotion" data-entity-id="{{this.id}}" data-name="{{this.banner-name}}" data-position="{{this.location}}" data-banner-id="{{this.banner-name}}">
        <div data-event-type="promotion-click">
            {{{this.content}}}
        </div>
    </div>
    {{/each}}
</div>
{{/if}}

components/common/currency-selector:
{{#if currency_selector.currencies.length '>' 1}}
        <a class="navUser-action navUser-action--currencySelector has-dropdown"
           href="#"
           data-dropdown="currencySelection"
           aria-controls="currencySelection"
           aria-expanded="false"
        >
            {{lang 'common.currency' code=currency_selector.active_currency_code}}
            <i class="icon" aria-hidden="true">
                <svg>
                    <use xlink:href="#icon-chevron-down" />
                </svg>
            </i>
        </a>
        <ul class="dropdown-menu" id="currencySelection" data-dropdown-content aria-hidden="true" tabindex="-1">
            {{#each currency_selector.currencies}}
            <li class="dropdown-menu-item">
                <a href="{{{switch_url}}}"
                   data-currency-code="{{{code}}}"
                   {{#if cart_currency_switch_url.length '>' 0 }}
                   data-cart-currency-switch-url="{{{cart_currency_switch_url}}}"
                   {{/if}}
                   data-warning="{{lang 'common.currency_switch_promotion'}}"
                >
                {{#if is_active}}
                    <strong>{{name}}</strong>
                {{else}}
                    {{name}}
                {{/if}}
                </a>
            </li>
            {{/each}}
        </ul>
{{/if}}

components/common/channel-selector:
{{#if theme_settings.channels.length '>' 1}}
<ul class="navUser-section">
    <li class="navUser-item">
        <a href="#"
           class="navUser-action navUser-action--channelSelector has-dropdown"
           data-dropdown="channelSelection"
           aria-controls="channelSelection"
           aria-expanded="false"
        >
            {{#each theme_settings.channels}}
                {{#if is_active}}
                    {{lang 'common.channel' code=code}}
                {{/if}}
            {{/each}}
            <i class="icon" aria-hidden="true">
                <svg>
                    <use href="#icon-chevron-down"/>
                </svg>
            </i>
        </a>
        <ul class="dropdown-menu" id="channelSelection" data-dropdown-content aria-hidden="true" tabindex="-1">
            {{#each theme_settings.channels}}
                <li class="dropdown-menu-item">
                    <a href="{{{switch_url}}}" data-channel-code="{{{code}}}" data-warning="{{lang 'common.channel_switch_warning'}}">
                        {{#if is_active}}
                            <strong>{{name}}</strong>
                        {{else}}
                            {{name}}
                        {{/if}}
                    </a>
                </li>
            {{/each}}
        </ul>
    </li>
</ul>
{{/if}}

components/common/social-links:
{{#if social_media}}
    <ul class="socialLinks socialLinks--alt">
        {{#each social_media}}
            <li class="socialLinks-item">
                <a class="icon icon--{{display_name}}" href="{{url}}" target="_blank" rel="noopener">
                    {{display_name}}
                    <svg><use xlink:href="#icon-{{display_name}}" /></svg>
                </a>
            </li>
        {{/each}}
    </ul>
{{/if}}

components/common/navigation-list-altern:
{{#if children}}
    <a class="navPages-action navPages-action-depth-max has-subMenu is-root{{#if is_active}} activePage{{/if}}"
       href="{{url}}"
       data-collapsible="navPages-{{id}}"
       aria-label="{{name}}"
    >
        {{name}}
        <i class="icon navPages-action-moreIcon" aria-hidden="true">
            <svg><use href="#icon-chevron-down" /></svg>
        </i>
    </a>
    {{> components/common/navigation-dropdown}}
{{else}}
    <a class="navPages-action{{#if is_active}} activePage{{/if}}"
       href="{{url}}"
       aria-label="{{name}}"
    >
        {{name}}
    </a>
{{/if}}

